// LOOP is the RIGHT tool here: nested matching, in-place mutation, break, try/catch, budget tracking
package com.bank.matching.service;

import com.bank.matching.dto.MatchingReport;
import com.bank.matching.model.Order;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class LoopMatchingService {

    private final EntityManager em;

    @Value("${matching.max-budget:500000}")
    private BigDecimal maxBudget;

    @Transactional
    public MatchingReport matchOrders() {
        List<Order> allOrders = em.createQuery("SELECT o FROM Order o WHERE o.status = 'OPEN'",
            Order.class).getResultList();

        List<Order> buys = new ArrayList<>();
        List<Order> sells = new ArrayList<>();
        for (Order o : allOrders) {
            if (o.isBuy()) buys.add(o); else sells.add(o);
        }

        // ═══ WHY LOOP: nested match + in-place mutation + budget + break + try/catch ═══
        List<String> matches = new ArrayList<>();
        BigDecimal totalMatched = BigDecimal.ZERO;
        int matchCount = 0;

        for (Order buy : buys) {
            if (!buy.isOpen()) continue;  // already matched in previous iteration

            for (Order sell : sells) {
                if (!sell.isOpen()) continue;

                // CASE 1: Index-like comparison — symbol + quantity must match
                if (!buy.getSymbol().equals(sell.getSymbol())) continue;
                if (buy.getQuantity() != sell.getQuantity()) continue;

                // CASE 2: Budget check with running total (stateful)
                BigDecimal matchValue = buy.getAmount();
                if (totalMatched.add(matchValue).compareTo(maxBudget) > 0) {
                    log.warn("Budget exhausted at Rs.{} — stopping", totalMatched);
                    break;  // CASE 5: break inner loop (stream can't do this cleanly)
                }

                // CASE 3: Per-element try/catch (checked exception handling)
                try {
                    settleMatch(buy, sell);  // might throw
                } catch (Exception e) {
                    log.error("Settlement failed for {} ↔ {}: {}",
                        buy.getOrderId(), sell.getOrderId(), e.getMessage());
                    continue;  // skip this pair, try next sell
                }

                // CASE 4: In-place modification (JPA dirty checking)
                buy.setStatus("MATCHED");
                sell.setStatus("MATCHED");

                totalMatched = totalMatched.add(matchValue);
                matchCount++;
                matches.add(buy.getOrderId() + " ↔ " + sell.getOrderId()
                    + " (" + buy.getSymbol() + " Rs." + matchValue + ")");
                log.info("(Recommended) Matched: {} ↔ {} for Rs.{}", buy.getOrderId(),
                    sell.getOrderId(), matchValue);

                break;  // CASE 5: matched this buy — move to next buy (break inner)
            }
        }

        return new MatchingReport("FOR-LOOP (right tool for matching)", matchCount,
            totalMatched, matches, Map.of(
                "nested_loop_break", "Need break inner + break outer for budget",
                "in_place_mutation", "JPA dirty checking needs entity.setStatus()",
                "try_catch", "Per-match settlement might throw checked exception",
                "stateful_budget", "Running total determines when to stop"));
    }

    private void settleMatch(Order buy, Order sell) throws Exception {
        // Simulates external settlement that might fail
        if ("WIPRO".equals(buy.getSymbol())) {
            throw new Exception("WIPRO settlement suspended by exchange");
        }
        log.info("  Settlement: {} buys from {} at Rs.{}", buy.getOrderId(),
            sell.getOrderId(), buy.getPrice());
    }
}
