// STREAM is the RIGHT tool here: filter, group, aggregate, report — no mutation, no exceptions
package com.bank.matching.service;

import com.bank.matching.model.Order;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class StreamAnalyticsService {

    private final EntityManager em;

    @Transactional(readOnly = true)
    public Map<String, Object> analyzeOrderBook() {
        List<Order> orders = em.createQuery("SELECT o FROM Order o", Order.class).getResultList();

        // ═══ STREAM shines: filter, group, aggregate — read-only, no exceptions ═══

        long openBuys = orders.stream().filter(Order::isBuy).filter(Order::isOpen).count();
        long openSells = orders.stream().filter(Order::isSell).filter(Order::isOpen).count();

        Map<String, Long> buysBySymbol = orders.stream()
            .filter(Order::isBuy).filter(Order::isOpen)
            .collect(Collectors.groupingBy(Order::getSymbol, Collectors.counting()));

        BigDecimal totalBuyValue = orders.stream()
            .filter(Order::isBuy).filter(Order::isOpen)
            .map(Order::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        String symbols = orders.stream()
            .map(Order::getSymbol).distinct().sorted()
            .collect(Collectors.joining(", "));

        Optional<Order> largestOrder = orders.stream()
            .max(Comparator.comparing(Order::getAmount));

        return Map.of(
            "openBuys", openBuys,
            "openSells", openSells,
            "buysBySymbol", buysBySymbol,
            "totalBuyValue", totalBuyValue,
            "symbols", symbols,
            "largestOrder", largestOrder.map(Order::getOrderId).orElse("none"),
            "approach", "STREAM (right tool for analytics — read-only, declarative)"
        );
    }
}
