package com.bank.matching.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class LoopVsStreamTest {

    // ═══ CASE 1: Index access — loop wins ═══
    @Test
    void indexAccessWithLoop() {
        List<Integer> prices = List.of(100, 105, 103, 110, 108);
        List<String> changes = new ArrayList<>();

        for (int i = 1; i < prices.size(); i++) {
            int diff = prices.get(i) - prices.get(i - 1);
            changes.add(diff > 0 ? "UP" : "DOWN");
        }
        assertThat(changes).containsExactly("UP", "DOWN", "UP", "DOWN");
    }

    // ═══ CASE 2: In-place modification — loop wins ═══
    @Test
    void inPlaceModificationWithLoop() {
        List<StringBuilder> names = new ArrayList<>(List.of(
            new StringBuilder("reliance"), new StringBuilder("tcs")));

        for (StringBuilder name : names) {
            name.replace(0, 1, name.substring(0, 1).toUpperCase());  // capitalize first letter
        }
        assertThat(names.get(0).toString()).isEqualTo("Reliance");
    }

    // ═══ CASE 3: Checked exception — loop wins ═══
    @Test
    void checkedExceptionWithLoop() {
        List<String> results = new ArrayList<>();
        List<String> inputs = List.of("100", "abc", "200");

        for (String input : inputs) {
            try {
                results.add("parsed: " + Integer.parseInt(input));
            } catch (NumberFormatException e) {
                results.add("error: " + input);
            }
        }
        assertThat(results).containsExactly("parsed: 100", "error: abc", "parsed: 200");
    }

    // ═══ CASE 4: Budget break — loop wins ═══
    @Test
    void budgetBreakWithLoop() {
        List<Integer> amounts = List.of(100, 200, 300, 400, 500);
        int budget = 500;
        int spent = 0;
        List<Integer> purchased = new ArrayList<>();

        for (int amount : amounts) {
            if (spent + amount > budget) break;
            spent += amount;
            purchased.add(amount);
        }
        assertThat(purchased).containsExactly(100, 200);  // 100+200=300, next 300 would exceed 500
    }

    // ═══ STREAM wins for analytics ═══
    @Test
    void streamWinsForAnalytics() {
        List<String> symbols = List.of("RELIANCE", "TCS", "RELIANCE", "HDFC", "TCS", "RELIANCE");

        Map<String, Long> frequency = symbols.stream()
            .collect(Collectors.groupingBy(s -> s, Collectors.counting()));

        assertThat(frequency).containsEntry("RELIANCE", 3L);
        assertThat(frequency).containsEntry("TCS", 2L);
        // This is 1 line with stream vs 8 lines with loop
    }

    // ═══ BOTH tools — use the RIGHT one ═══
    @Test
    void useRightToolForTheJob() {
        // Stream: filter + group + aggregate (READ-ONLY)
        var analytics = List.of(100, 200, 300, 400, 500).stream()
            .filter(n -> n > 150)
            .collect(Collectors.summarizingInt(Integer::intValue));
        assertThat(analytics.getSum()).isEqualTo(1400);

        // Loop: running total with conditional break (STATEFUL + EARLY EXIT)
        int runningMax = 0;
        int budget = 700;
        List<Integer> selected = new ArrayList<>();
        for (int n : List.of(200, 300, 400, 500)) {
            if (runningMax + n > budget) break;
            runningMax += n;
            selected.add(n);
        }
        assertThat(selected).containsExactly(200, 300);
    }
}
